head.script:
/**
 * 최상단(opener, parent 포함) 기준 함수
 */
scwin.isMain = function() {
    return true;
};

/**
 * 전역 변수
 *
 * ============ ============ ==========================
 *  Date         Author       Description
 * ============ ============ ==========================
 * 2022.05.10.   최연구       [NELS]최초생성
 * ============ ============ ==========================
 */
scwin.param   = {};  // 파라메터


scwin.onpageload = function() {
    ibx_answer.focus();
    
    // 4분마다 캡챠문자 갱신
    com.util.setInterval(
        function() {
            btn_reloadCaptcha.trigger("onclick");
        },
        { delay : 1000*60*4, key : "loginTimeout" }
    );
        
    scwin.param = ssgo.getParameter();

    // captcha정보 로드
    com.executeSubmission(sbm_captcha);    
};

scwin.onpageunload = function() {
};


/**
 *********************************************************************************************************
 * Submission Event Handler
 *********************************************************************************************************
 */
/**
 * 캡챠정보 조회 submission done 이벤트
 *
 * ============ ============ ==========================
 *  Date         Author       Description
 * ============ ============ ==========================
 * 2022.05.10.   최연구       [NELS]최초생성
 * ============ ============ ==========================
 */
scwin.sbm_captcha_submitdone = function(e) {
   
    const captcha = document.querySelector(".form");
    
    const image = dma_captchaInf.get("image");

    const binary = ssgo.fixBinary(atob(image));
    const blob = new Blob([binary], { type: 'image/png' });

    const url = URL.createObjectURL(blob);     
    
    const img = captcha.querySelector("img");
    img.setAttribute('src', url);
}

/**
 * 캡챠정보 조회 submission error 이벤트
 *
 * ============ ============ ==========================
 *  Date         Author       Description
 * ============ ============ ==========================
 * 2022.05.10.   최연구       [NELS]최초생성
 * ============ ============ ==========================
 */
scwin.sbm_captcha_submiterror = function(e) {
    ssgo.printSubmiterror(e);
};

/**
 *********************************************************************************************************
 * Event Handler
 *********************************************************************************************************
 */
/**
 * 검색버튼 클릭 이벤트
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.06.24.   최연구       [NELS]최초생성
 * ============= ============ ==========================
 */
scwin.btn_srchCs_onclick = function(e) {
    var param = scwin.param;

    // 정합성 체크
    if(!scwin.vfn_validateCsSrch()) {
        return false;
    }

    // 캡차정보 셋팅   
    param.captchaAnswer = ibx_answer.getValue();
    param.encCaptchaAnswer = dma_captchaInf.get("answer");
    param.callDomain = "selfDomain";
    
    //TODO : 연계팝업 함로로 호출해야함.
    window.open("" ,"csSrchDetail", "toolbar=no, width=1100, height=800, directories=no, status=no, scrollorbars=no, resizable=no"); 
    ssgo.sendPostForm(ssgo.getCtxtPathUrl("/srchCsDetail.on"), param, "csSrchDetail"); 

    // 검색후 메인으로 이동
    //com.movePage("/ssgo/srchMyCsForPsp.on");
};

/**
 * 자동입력방지(캡챠) 이미지 리로딩
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.06.24.   최연구       [NELS]최초생성
 * ============= ============ ==========================
 */
scwin.btn_reloadCaptcha_onclick = function(e) {
    com.executeSubmission(sbm_captcha);
};

/**
 * 캡챠 음성듣기
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.06.24.   최연구       [NELS]최초생성
 * ============= ============ ==========================
 */
scwin.btn_voiceListen_onclick = function(e) {
    if(!scutilo.isEmpty(dma_captchaInf) && dma_captchaInf.get("audio")){
        const binary = ssgo.fixBinary(atob(dma_captchaInf.get("audio")));
        const blob = new Blob([binary], { type: 'audio/wave' });
        const url = URL.createObjectURL(blob);
        new Audio(url).play();
    }    
};

scwin.btn_before_onclick = function(e) {
    // 메인으로 이동
    //com.movePage("/ssgo/srchMyCsForPsp.on");
    ssgo.sendPostForm(ssgo.getCtxtPathUrl("/srchMyCsForPsp.on"), {});
};


/**
 *********************************************************************************************************
 * Validate 
 *********************************************************************************************************
 */
/**
 * 사건검색 검색조건 정합성 체크
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.06.24.   최연구       [NELS]최초생성
 * ============= ============ ==========================
 */
scwin.vfn_validateCsSrch = function() {
    var param  = scwin.param;
    var answer = ibx_answer.getValue();

    if(scutilo.isEmpty(param.cortCd)) {
        scwin.ufn_ssgoPostMsg(scutilo.getMsg(ssgomsg.SSGO.I_0009, "법원 정보가"));
        return false;
    }

    if(scutilo.isEmpty(param.csDvsCd)) {
        scwin.ufn_ssgoPostMsg(scutilo.getMsg(ssgomsg.SSGO.I_0009, "사건구분 정보가"));
        return false;
    }

    if(scutilo.isEmpty(param.csSerial)) {
        scwin.ufn_ssgoPostMsg(scutilo.getMsg(ssgomsg.SSGO.I_0009, "사건일련번호 정보가"));
        return false;
    }

    var  anum=/(^\d+$)|(^\d+\.\d+$)/  
    if(!anum.test(param.csSerial)) {
        scwin.ufn_ssgoPostMsg(scutilo.getMsg(ssgomsg.SSGO.I_0003, "사건일련번호는"));
        return false;
    }

    // [사건검색]홈페이지 사건검색 금칙어 처리
    btprNm = param.btprtNm.replace(/\s/g, '');
    if(btprNm === "당사자명필수입력" || btprNm.length < 2 ) {
        scwin.ufn_ssgoPostMsg(scutilo.getMsg(ssgomsg.SSGO.I_0002, "당사자명을 2자이상"));
        return false;
    }

    var filter_word = /[$\\\\#\%\^\&\*\+\_\`\~\=\|\,\'\"\-\:\;\％\/]/;  //특수문자를 배열
    if (btprNm.search(filter_word)>=0) {
        scwin.ufn_ssgoPostMsg(scutilo.getMsg(ssgomsg.SSGO.I_0004, "당사자명에"));
        return false;
    }

    // 대법원 홈페이지 사건검색에서 금칙어를 사용 할 수 없도록 처리
    var psBanWordList = ssgo.getProperties("clt.ssgo.ban.word.list");
    var lines = psBanWordList.split(",");

    // 홈페이지 사건검색 금칙어 처리
    if( psBanWordList.indexOf(btprNm)>=0 ) {
        // 금칙어 추가 및 메세지 처리
        scwin.ufn_ssgoPostMsg(scutilo.getMsg(ssgomsg.SSGO.I_0005, btprNm, btprNm));
        return false;
    }

    answer = answer.replace(/\s/g, '');
    if ( answer.length != 6 ) {
        scwin.ufn_ssgoPostMsg(scutilo.getMsg(ssgomsg.SSGO.I_0001, "자동입력 방지 문자 6자를"));
        ibx_answer.focus();
        return false;
    }    
    
    // 캡챠암호화 문자체크
    var encAnswer = dma_captchaInf.get("answer");
    if(scutilo.isEmpty(encAnswer)) {
        scwin.ufn_ssgoPostMsg(scutilo.getMsg(ssgomsg.SSGO.E_0007, "캡챠 랜더링"));
        return false;
    }

    return true;
}


/**
 *********************************************************************************************************
 * User Function
 *********************************************************************************************************
 */


/**
 * 사건검색 Iframe의 부모객체에 값을 전달한다.
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.06.24.   최연구       [NELS]최초생성
 * ============= ============ ==========================
 */
scwin.ufn_ssgoPostMsg = function(msg) {
    
    if(!scutilo.isEmpty(msg)) {
        try{
            window.parent.postMessage({ othrDmnMsg : msg }, ssgo.getProperties("clt.ssgo.ecf.domain"));
        }catch (e) {
            console.log("허용된 도메인이 아닙니다.");
        }
    }

};
